/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var isNonNegativeNumber = require( '@stdlib/assert/is-nonnegative-number' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Sets the position of the y axis.
* Note: y axis is horizontel axis, this setter take the height( row Number ) for position.
*
* @private
* @param {Number} value - position( row Number )
* @throws {TypeError} must be a non negative number
*/
function set( value ) {
	if ( !isNonNegativeNumber( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a non negative number. Value: `%s`.', 'yAxisPos', value ) );
	}
	if ( this._axisDataObjs[ 1 ].position !== value ) {
		this._axisDataObjs[ 1 ].position = value;
		if ( !this._quite ) {
			this.emit( 'change' );
		}
	}
}


// EXPORTS //

module.exports = set;
